// <auto-generated />
export interface DiscardNoteRequest {
  readonly title: string;
  readonly bodyLength: number;
}

/**
 * A pane of the document page.
 *
 * - `Editor`: The note editor.
 * - `Preview`: The rendered note.
 */
export type DocumentPane = "Editor" | "Preview";

/**
 * How the activation hooks of a committed transition ended (`Activation`).
 *
 * - `None`: No entry the commit made current has an activation hook.
 * - `Completed`: Every activation hook returned.
 * - `Failed`: An activation hook threw; the commit stands.
 * - `Cancelled`: An activation hook was cancelled, because its entry stopped being current or retired, or the navigator closed, or it was never started for that reason.
 */
export type NavigationActivationState = "None" | "Completed" | "Failed" | "Cancelled";

/** A summary of a `NavigationResult` without its .NET content and exception, so a ViewModel can return it to a Runic View, for example as the output of a back command. */
export interface NavigationOutcome {
  /** How the request ended. */
  readonly kind: NavigationOutcomeKind;
  /** Why the request was rejected, for `Rejected`; otherwise `null`. */
  readonly rejection: NavigationRejection | null;
  /** Gets how the activation hooks (`INavigationActivated`) of the entries a `Committed` transition made current ended, so a page can show that their data failed to load; `None` for every other kind. Only the full navigation result carries the exception of a `Failed` hook. */
  readonly activation: NavigationActivationState;
}

/**
 * How a navigation request ended, as reported by `Kind`.
 *
 * - `Committed`: The transition committed.
 * - `Rejected`: The transition was rejected; `Rejection` says why.
 * - `Superseded`: A later request replaced this one before it committed.
 * - `Failed`: The transition failed. Only the full navigation result carries the exception.
 */
export type NavigationOutcomeKind = "Committed" | "Rejected" | "Superseded" | "Failed";

/**
 * Why a navigation request was rejected.
 *
 * - `Guard`: A departure guard returned `false`.
 * - `Cancelled`: The caller's token was cancelled before the commit.
 * - `Closed`: The navigator or the region is closed.
 * - `Reentrant`: The request came from a hook of an in-flight transition of the same region, or of a region that holds it or is held by it (an ancestor or a descendant region). The rejection is conservative: such a request could wait on the transition that is running the hook.
 * - `NoHistory`: A back request found no retained entry.
 * - `NotCurrent`: The expected current entry is not current.
 * - `EntryNotFound`: The back-to target is not in the region.
 * - `Busy`: The region admits requests with `RejectWhileBusy` and was busy: an earlier request had not completed.
 */
export type NavigationRejection = "Guard" | "Cancelled" | "Closed" | "Reentrant" | "NoHistory" | "NotCurrent" | "EntryNotFound" | "Busy";

/** Why a note could not be saved. */
export type SaveFailure =
  | { readonly $case: "titleRequired" }
  | ({ readonly $case: "titleTooLong" } & TitleTooLong);

/** The title is longer than the notes store accepts. */
export interface TitleTooLong {
  readonly maximumLength: number;
}
